        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var esg = lastResult.esgScore || 0;
            var ebitda = lastResult.ebitdaMargin || 0;
            var lentia = lastResult.lentiaScore || 0;
            var greenwash = lastResult.greenwashIndex || 0;
            var trust = lastResult.stakeholderTrust || 0;
            var carbon = lastResult.carbonTotal || 14410;

            var esgWeight = 0.35;
            var finWeight = 0.25;
            var lentiaWeight = 0.20;
            var gwWeight = 0.10;
            var trustWeight = 0.10;

            var esgPct = Math.min(100, (esg / 1000) * 100);
            var finPct = ebitda >= 8.5 ? 100 : (ebitda >= 7 ? 70 : (ebitda >= 5 ? 40 : 10));
            var lentiaPct = Math.min(100, lentia);
            var gwPct = greenwash;
            var trustPct = trust;

            var composite = Math.round(
                esgPct * esgWeight +
                finPct * finWeight +
                lentiaPct * lentiaWeight +
                gwPct * gwWeight +
                trustPct * trustWeight
            );

            var performanceKey = 'perf_needs';
            if (composite >= 75) performanceKey = 'perf_excellent';
            else if (composite >= 60) performanceKey = 'perf_good';
            else if (composite >= 45) performanceKey = 'perf_satisfactory';
            var performanceId = performanceKey.replace('perf_', '');

            // EQIL 2026-11-12: run-specific debrief built from the history (turning point and mistakes made)
            var h1 = history[0] || {}, h2 = history[1] || {}, h3 = history[2] || {};
            var d1 = h1.decisions || {}, d2 = h2.decisions || {}, d3 = h3.decisions || {};
            var lastDs = history[history.length - 1].domainState || {};
            var hadGHG = (d1.initiatives || []).indexOf('ghg') !== -1;
            var mistakeKeys = [];
            if (d1.supplierResponse === 'ignore') mistakeKeys.push('dbr_m_ignore');
            if (d1.supplierResponse === 'terminate') mistakeKeys.push('dbr_m_terminate');
            if (history.length >= 2 && d2.reportTone === 'aspirational') mistakeKeys.push('dbr_m_aspirational');
            if (history.length >= 2 && d2.laborResponse === 'pr_statement') mistakeKeys.push('dbr_m_pr');
            if (history.length >= 3 && !hadGHG && d3.greenBond === 'yes') mistakeKeys.push('dbr_m_bond');
            var turningKey;
            if (lastDs.lentiaLost) turningKey = 'dbr_tp_lentia_lost';
            else if (mistakeKeys.length) turningKey = mistakeKeys.shift();
            else if (history.length >= 3 && hadGHG && d3.greenBond === 'yes') turningKey = 'dbr_tp_enabler';
            else turningKey = 'dbr_tp_none';

            var insightKeys = [];
            insightKeys.push(esg >= 600 ? 'ins_esg_ok' : 'ins_esg_low');
            insightKeys.push(carbon <= 10087 ? 'ins_carbon_ok' : 'ins_carbon_miss');
            if (!lastDs.lentiaLost) insightKeys.push(lentia >= 70 ? 'ins_lentia_ok' : 'ins_lentia_miss');
            if (ebitda < 8.5) { insightKeys.push('ins_ebitda_low'); }
            if (greenwash < 85) { insightKeys.push('ins_greenwash_low'); }
            var self = this;
            var insights = [turningKey].concat(mistakeKeys, insightKeys).map(function(k) { return self._t(k); });

            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performanceLabel: this._t(performanceKey),
                turningKey: turningKey,
                mistakeKeys: mistakeKeys,
                insightKeys: insightKeys,
                stakeholderTrust: trust,
                compositeScore: composite,
                esgRating: this._getESGRating(esg),
                esgScore: esg,
                ebitdaMargin: ebitda,
                carbonReduction: Math.round(((14410 - carbon) / 14410) * 100),
                lentiaScore: lentia,
                greenwashIndex: greenwash,
                performance: performanceId,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var t = function(k) { return self._t(k); };
            var es = (window.vcI18n && window.vcI18n._lang) === 'es';
            var num = function(v, dec) { var x = (Number(v) || 0).toFixed(dec); return es ? x.replace('.', ',') : x; };
            var kpi = function(label, value) {
                return '<div class="biotex-sim-cm-kpi"><span class="biotex-sim-cm-kpi-label">' + label + '</span><span class="biotex-sim-cm-kpi-value">' + value + '</span></div>';
            };
            var li = function(keys) { return (keys || []).map(function(k) { return '<li>' + t(k) + '</li>'; }).join(''); };
            var html = '<div class="biotex-sim-cm">';
            html += '<div class="biotex-sim-cm-head"><div class="biotex-sim-cm-score">' + (s.composite != null ? s.composite : 0) + '<span>/100</span></div>';
            html += '<div class="biotex-sim-cm-tier">' + (s.performanceLabel || '') + '</div></div>';
            html += '<div class="biotex-sim-cm-kpis">' +
                kpi(t('esg_label'), Math.round(s.esgScore || 0) + '/1000 (' + (s.esgRating || '') + ')') +
                kpi(t('ebitda_label'), num(s.ebitdaMargin, 2) + '%') +
                kpi(t('dbr_carbon'), (s.carbonReduction || 0) + '%') +
                kpi(t('lentia_label'), Math.round(s.lentiaScore || 0) + '/100') +
                kpi(t('greenwash_label'), Math.round(s.greenwashIndex || 0) + '/100') +
                kpi(t('trust_label'), Math.round(s.stakeholderTrust || 0) + '/100') + '</div>';
            if (s.turningKey) html += '<h4 class="biotex-sim-cm-h">' + t('dbr_tp') + '</h4><p class="biotex-sim-cm-tp">' + t(s.turningKey) + '</p>';
            if (s.mistakeKeys && s.mistakeKeys.length) html += '<h4 class="biotex-sim-cm-h">' + t('dbr_decisions') + '</h4><ul>' + li(s.mistakeKeys) + '</ul>';
            html += '<h4 class="biotex-sim-cm-h">' + t('dbr_takeaways') + '</h4><ul>' + li(s.insightKeys) + '</ul>';
            html += '<h4 class="biotex-sim-cm-h">' + t('dbr_questions') + '</h4><ol>' + li(['dbr_q1', 'dbr_q2', 'dbr_q3']) + '</ol>';
            return html + '</div>';
        }

